        ArgumentException.ThrowIfNullOrEmpty(warehouse.Code);
        ArgumentOutOfRangeException.ThrowIfNegative(counted);

        store.Set(item.Sku, counted);
        var variance = counted - item.OnHand;
        var status = variance == 0 ? CountStatus.Match
            : Math.Abs(variance) > 100 ? CountStatus.LargeVariance
            : counted == 0 && item.OnHand > 0 ? CountStatus.Zeroed
            : CountStatus.Recorded;
        return new(status, variance);
    }
}

